func mergeSort(a []int, l, r int, count *int) {
	m := (l + r) / 2
	mergeSort(a, l, m, count)
	mergeSort(a, m+1, r, count)
	i, j := l, m+1
	for i <= m && j <= r {
		if a[i] < a[j] {
			temp = append(temp, a[i])
			i++
		} else {
			temp = append(temp, a[j])
			j++
			*count += m - i + 1
		}
	}
	fmt.Printf("merge [%d..%d]:", l, r)
	for _, n := range a[l : r+1] {
		fmt.Printf(" %d", n)
	}
	fmt.Println()
}
